create table if not exists public.sat_sessions (id uuid primary key,user_id uuid references auth.users(id) on delete cascade default auth.uid(),started_at timestamptz not null,ended_at timestamptz not null,mode text not null check(mode in ('english','math','both')),question_count int not null check(question_count>0));
create table if not exists public.sat_attempts (id uuid primary key,user_id uuid references auth.users(id) on delete cascade default auth.uid(),session_id uuid not null,question_id text not null,subject text not null check(subject in ('english','math')),module text not null,question_number int not null,selected_answer text not null,correct_answer text not null,correct boolean not null,self_graded boolean not null default false,elapsed_ms int not null check(elapsed_ms>=0),created_at timestamptz not null default now());
alter table public.sat_sessions enable row level security;alter table public.sat_attempts enable row level security;
create policy "users own sessions" on public.sat_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users own attempts" on public.sat_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists sat_attempts_user_created_idx on public.sat_attempts(user_id,created_at desc);create index if not exists sat_attempts_question_idx on public.sat_attempts(user_id,question_id);
